// Rule Engine: Giam sat nguong chat luong nuoc va ra quyet dinh dieu khien suc khi
// Input: msg.payload tu Orion Context Broker (NGSI-v2 Subscription)

const data = msg.payload.data;
if (!Array.isArray(data) || data.length === 0) {
    return null;
}

// Ham trich xuat gia tri thuoc tinh (ho tro ca keyValues va normalized format)
function getAttrValue(entity, attrName) {
    if (!entity || entity[attrName] === undefined || entity[attrName] === null) return null;
    if (typeof entity[attrName] === 'object' && entity[attrName] !== null && 'value' in entity[attrName]) {
        return entity[attrName].value;
    }
    return entity[attrName];
}

const commands = [];
const alerts = [];

for (let i = 0; i < data.length; i++) {
    const pond = data[i];
    const pondId = pond.id; // vi du: urn:ngsi-ld:Pond:001
    const doVal = getAttrValue(pond, 'dissolvedOxygen');
    const phVal = getAttrValue(pond, 'pH');
    const tempVal = getAttrValue(pond, 'temperature');
    const salVal = getAttrValue(pond, 'salinity');
    const aeratorState = (getAttrValue(pond, 'aeratorState') || '').toUpperCase();

    let targetAerator = null;
    let triggerReason = '';

    // RULE 1: Nhiet do cao (> 33 oC) -> Canh bao + kich hoat suc khi
    if (tempVal !== null && tempVal > 33.0) {
        alerts.push({
            pondId: pondId,
            level: 'WARNING',
            metric: 'temperature',
            value: tempVal,
            message: `[${pondId}] Nhiet do nuoc cao (${tempVal} oC > 33 oC). Bat suc khi ho tro!`,
            timestamp: new Date().toISOString()
        });
        targetAerator = 'ON';
        triggerReason = `Nhiet do cao (${tempVal} oC)`;
    }

    // RULE 2: Nguong Oxy hoa tan (DO)
    // - DO < 4.0 mg/L -> Bat suc khi
    // - DO > 6.0 mg/L -> Tat suc khi (Hysteresis chong dong ngat lien tuc)
    if (doVal !== null) {
        if (doVal < 4.0) {
            targetAerator = 'ON';
            triggerReason = `DO thap (${doVal} mg/L < 4.0 mg/L)`;
            if (doVal < 2.5) {
                alerts.push({
                    pondId: pondId,
                    level: 'CRITICAL',
                    metric: 'dissolvedOxygen',
                    value: doVal,
                    message: `[${pondId}] NGUY CAP! DO tut sau (${doVal} mg/L < 2.5 mg/L). Bat suc khi khan cap!`,
                    timestamp: new Date().toISOString()
                });
            } else {
                alerts.push({
                    pondId: pondId,
                    level: 'WARNING',
                    metric: 'dissolvedOxygen',
                    value: doVal,
                    message: `[${pondId}] Canh bao: DO thap (${doVal} mg/L < 4.0 mg/L). Bat suc khi.`,
                    timestamp: new Date().toISOString()
                });
            }
        } else if (doVal > 6.0 && (tempVal === null || tempVal <= 33.0)) {
            targetAerator = 'OFF';
            triggerReason = `DO doi dao (${doVal} mg/L > 6.0 mg/L)`;
        }
    }

    // RULE 3: pH bat thuong ngoai khoang 7.5 - 8.5
    if (phVal !== null && (phVal < 7.5 || phVal > 8.5)) {
        alerts.push({
            pondId: pondId,
            level: 'WARNING',
            metric: 'pH',
            value: phVal,
            message: `[${pondId}] Canh bao: pH bat thuong (${phVal} nam ngoai 7.5 - 8.5)!`,
            timestamp: new Date().toISOString()
        });
    }

    // Chi gui lenh khi can chuyen doi trang thai thuc su
    if (targetAerator !== null && targetAerator !== aeratorState) {
        commands.push({
            url: `http://orion:1026/v2/entities/${encodeURIComponent(pondId)}/attrs`,
            method: 'PATCH',
            headers: {
                'Content-Type': 'application/json',
                'fiware-service': 'shrimp',
                'fiware-servicepath': '/'
            },
            payload: {
                'aerator': {
                    'type': 'command',
                    'value': targetAerator
                }
            },
            info: `[${pondId}] Chuyen aerator tu ${aeratorState || 'UNKNOWN'} sang ${targetAerator} do ${triggerReason}`,
            pondId: pondId,
            targetAerator: targetAerator
        });
    }
}

// Output 1: Danh sach lenh dieu khien gui toi Orion
// Output 2: Danh sach canh bao (Alerts)
const alertMsg = alerts.length > 0 ? { payload: alerts } : null;
return [commands, alertMsg];
